+Ref<ShaderMaterial> TextShaderPreview::get_source_material() const {
+	Object *object = InspectorDock::get_inspector_singleton()->get_edited_object();
+	Ref<ShaderMaterial> src_mat;
+
+	if (object) {
+		if (object->has_method("get_active_material")) {
+			Ref<Mesh> mesh = Object::cast_to<Mesh>(object->call("get_mesh"));
+			if (mesh.is_valid()) {
+				int surface_count = mesh->get_surface_count();
+				bool found = false;
+
+				for (int i = 0; i < surface_count; i++) {
+					src_mat = Object::cast_to<ShaderMaterial>(object->call("get_active_material", i));
+
+					if (src_mat.is_null() || !_match_uniforms(src_mat, shader_material)) {
+						continue;
+					}
+
+					found = true;
+					break;
+				}
+
+				if (!found) {
+					return Ref<ShaderMaterial>();
+				}
+
+				return src_mat;
+			} else {
+				src_mat = Object::cast_to<ShaderMaterial>(object->call("get_active_material", 0));
+			}
+		} else if (object->has_method("get_material")) {
+			src_mat = Object::cast_to<ShaderMaterial>(object->call("get_material"));
+		}
+	}
+
+	if (src_mat.is_null() || !_match_uniforms(src_mat, shader_material)) {
+		return Ref<ShaderMaterial>();
+	}
+
+	return src_mat;
+}
+
+void TextShaderPreview::sync_shader_parameters() {
+	if (shader_material->get_shader().is_null()) {
+		return;
+	}
+	Ref<ShaderMaterial> src_mat = get_source_material();
+	if (src_mat.is_null()) {
+		_show_error(TTR("A node using the shader must be selected."));
+		return;
+	}
+	_sync_shader_parameters(src_mat, shader_material);
+}
